// UI translations (#143). The key of every string is its English text: i18n/en.json
// lists them (generated by Tools/i18n-extract.py) and i18n/<code>.json holds one
// language's translations, edited on Weblate. A missing or empty entry shows English.
//
// The page is written in English and translated in place: every text node and
// title / placeholder / aria-label attribute whose text is a key is swapped for its
// translation, and a MutationObserver does the same for whatever the app renders later.
// So markup and most script strings need no changes — see Docs/TRANSLATIONS.md.
//
//   tr('Save')                     marks a script string for en.json; returns it unchanged
//                                  (it is translated when it reaches the page)
//   tr('Pass {n}', { n: 3 })       strings with values: translated and filled in here
//   tr('all', {})                  a string joined into a longer one: translated here too
//   translate="no"                 on an element: leave its contents alone (names, logs)
const I18n = (() => {
  const ATTRS = ['title', 'placeholder', 'aria-label'];
  const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'TEXTAREA']);
  const HAS_WORD = /\p{L}{2}/u; // "—", "0.0", "✕" are never keys

  let lang = 'en';
  let dict = null;              // key → translation; null = English
  let loadSeq = 0;
  const textState = new WeakMap();  // text node → { src, out }
  const attrState = new WeakMap();  // element → { attr: { src, out } }
  // Text made by tr(key, params) → how to make it again in another language.
  const produced = new Map();
  const PRODUCED_MAX = 2000;

  const norm = s => s.replace(/\s+/g, ' ').trim();
  const lookup = key => (dict && dict[key]) || key;
  const fill = (s, params) => s.replace(/\{(\w+)\}/g, (m, name) => (name in params ? String(params[name]) : m));

  function t(key, params) {
    if (!params) return key;
    const out = fill(lookup(key), params);
    const k = norm(out);
    produced.delete(k);
    produced.set(k, { key, params });
    if (produced.size > PRODUCED_MAX) produced.delete(produced.keys().next().value);
    return out;
  }

  // The text to show for `src` (what the app wrote) in the current language.
  function render(src) {
    // "Wheelbase (" before a unit label is the key "Wheelbase": the " (" is kept as is.
    const tail = src.match(/\s*\(?\s*$/)[0];
    const key = norm(src.slice(0, src.length - tail.length));
    if (!key || !HAS_WORD.test(key)) return src;
    const p = produced.get(key);
    const out = p ? fill(lookup(p.key), p.params) : lookup(key);
    if (out === key) return src;
    return src.match(/^\s*/)[0] + out + tail;
  }

  // `st` remembers what the app wrote; if the current value isn't what we put there,
  // the app has written something new.
  function resolve(st, cur) {
    const src = st && st.out === cur ? st.src : cur;
    return { src, out: render(src) };
  }

  function skipped(el) {
    return !el || SKIP_TAGS.has(el.tagName) || el.closest('[translate="no"]') !== null;
  }

  function applyText(node) {
    const parent = node.parentElement;
    if (skipped(parent)) return;
    const cur = node.nodeValue;
    const st = resolve(textState.get(node), cur);
    textState.set(node, st);
    if (st.out === cur) return;
    // An <option> with no value attribute takes its value from its text: pin it first,
    // so the value the app reads and sends stays the English one.
    if (parent.tagName === 'OPTION' && !parent.hasAttribute('value')) parent.setAttribute('value', st.src);
    node.nodeValue = st.out;
  }

  function applyAttrs(el, only) {
    if (skipped(el)) return;
    let states = attrState.get(el);
    for (const a of only || ATTRS) {
      const cur = el.getAttribute(a);
      if (cur == null) continue;
      if (!states) attrState.set(el, states = {});
      const st = states[a] = resolve(states[a], cur);
      if (st.out !== cur) el.setAttribute(a, st.out);
    }
  }

  function walk(root) {
    if (root.nodeType === Node.TEXT_NODE) { applyText(root); return; }
    if (root.nodeType !== Node.ELEMENT_NODE) return;
    applyAttrs(root);
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
    for (let n = w.nextNode(); n; n = w.nextNode()) {
      if (n.nodeType === Node.TEXT_NODE) applyText(n); else applyAttrs(n);
    }
  }

  const observer = new MutationObserver(records => {
    for (const r of records) {
      if (r.type === 'characterData') applyText(r.target);
      else if (r.type === 'attributes') applyAttrs(r.target, [r.attributeName]);
      else for (const n of r.addedNodes) walk(n);
    }
  });
  let observing = false;
  function observe(on) {
    if (on === observing) return;
    observing = on;
    if (on) observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ATTRS });
    else observer.disconnect();
  }

  async function fetchDict(code) {
    // "pt-BR" falls back to "pt".
    for (const c of code.includes('-') ? [code, code.split('-')[0]] : [code]) {
      try {
        const r = await fetch('/i18n/' + encodeURIComponent(c) + '.json', { cache: 'no-store' });
        if (r.ok) return await r.json();
      } catch { /* offline or bad file: English */ }
    }
    return null;
  }

  async function setLanguage(code) {
    code = code || 'en';
    if (code === lang) return;
    lang = code;
    const seq = ++loadSeq;
    const d = code === 'en' ? null : await fetchDict(code);
    if (seq !== loadSeq) return; // a newer choice won
    dict = d;
    try { localStorage.setItem('agopenweb.lang', code); } catch { /* private mode */ }
    document.documentElement.lang = code;
    observe(false);
    walk(document.body);
    observe(dict !== null); // English needs no watching
  }

  // Start in the last language used here, so the page doesn't flash English while the
  // host's choice is on its way.
  try { const saved = localStorage.getItem('agopenweb.lang'); if (saved) setLanguage(saved); } catch { /* private mode */ }

  // text(key): the translation right now, for text drawn on a canvas.
  return { t, text: lookup, setLanguage, get language() { return lang; } };
})();
const tr = I18n.t;
